def deny = { ->
    def language = org.springframework.context.i18n.LocaleContextHolder.getLocale().getLanguage()
    def message = language == 'zh' ? '需要产品写入权限' : 'Product write permission is required'
    throw new net.ibizsys.runtime.util.ErrorException(message, net.ibizsys.runtime.util.Errors.ACCESSDENY)
}
def actor = net.ibizsys.runtime.security.UserContext.getCurrent()
if (actor == null || actor.isAnonymoususer() || !actor.getUserid()?.trim() || !actor.getOrgid()?.trim()) {
    deny()
}
def incoming = logic.param('Default').getReal()
def productId = incoming.get('product_id')
def id = incoming.get('id')
def idea = sys.getDataEntityRuntime('idea')
if (id != null && idea.checkKeyState(id) == net.ibizsys.runtime.dataentity.action.CheckKeyStates.EXIST) {
    def stored = idea.getSimpleEntity(id)
    def storedProductId = stored.get('product_id')
    if (productId != null && productId != storedProductId) {
        deny()
    }
    productId = storedProductId
}
if (!(productId instanceof String) || productId.trim().isEmpty()) {
    deny()
}
def product = sys.getDataEntityRuntime('product')
if (product.checkKeyState(productId) != net.ibizsys.runtime.dataentity.action.CheckKeyStates.EXIST) {
    deny()
}
if (!product.getDataEntityAccessManager().testDataAccessActionIf(actor, productId, 'SUBDATA')) {
    deny()
}
